  "tip.ram_single.t": "RAM がシングル チャネルで動作しています",
  "tip.ram_single.d": "メモリが 1 枚だとメモリ帯域が半分になります。同じ仕様のメモリをもう 1 枚追加すると、CPU 負荷の高いゲームで FPS が 10～30% 向上することがあります。",
