  "tip.ram_xmp.d": "メモリは {rated} MT/s 対応ですが、{cur} MT/s で動作しています。BIOS で XMP または EXPO を有効にすると、無料で性能が上がります。",
  "tip.ram_low.t": "RAM {gb} GB は最近のゲームには不足気味です",
  "tip.ram_low.d": "プレイ前にバックグラウンド アプリを閉じ、メモリ圧縮はオンのままにしてください。現在、快適に遊べる最低ラインは 16 GB です。",
  "tip.hdd_system.t": "Windows がハード ディスクにインストールされています",
  "tip.hdd_system.d": "SSD は読み込み時間とカクつきの改善に最も効果のあるアップグレードです。安価な SATA SSD でも大きな効果があります。",
  "tip.disk_low.t": "システム ドライブの空き容量が {gb} GB しかありません",
  "tip.disk_low.d": "Windows とゲームは、更新やシェーダー キャッシュのために空き容量を必要とします。一時ファイルを削除するか、ゲームを別のドライブに移動してください。",
  "tip.wifi.t": "Wi-Fi でゲームをしています",
  "tip.wifi.d": "Wi-Fi では遅延の急上昇やパケット ロスが発生します。Ethernet ケーブルが最も安定した ping をもたらします。",
  "tip.hz60.t": "ディスプレイが {hz} Hz で動作しています",
  "tip.hz60.d": "モニターがより高いリフレッシュ レートに対応している場合は、Windows のディスプレイ設定で設定し、DisplayPort または HDMI 2.0 ケーブルを使用してください。",
  "tip.hz60.a": "ディスプレイ設定",
  "tip.vbs.t": "メモリ整合性がオンです",
